// Everything a human sets, in one place.
const VAULT_PATH = '';              // TODO: the vault folder as n8n sees it, e.g. /data/vault
const ALLOWED_CHAT_IDS = [];        // TODO: ['123456789'] - only these chats are answered
const SUPABASE_URL = '';            // TODO: https://<project>.supabase.co
const INBOX_FOLDER = 'Inbox';
const TIMEZONE = 'Europe/Madrid';
const MODEL = 'claude-haiku-4-5';
const TRANSCRIBE_MODEL = 'whisper-1';
const MAX_SECONDS = 600;            // a ten minute cap, so one long recording cannot run away
const MAX_TAGS = 6;

if (!VAULT_PATH) throw new Error('VAULT_PATH is not configured in "Config"');
if (!ALLOWED_CHAT_IDS.length) throw new Error('ALLOWED_CHAT_IDS is empty in "Config"');
if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Config"');

return [{
  json: {
    vaultPath: VAULT_PATH.replace(/\/+$/, ''),
    inboxFolder: INBOX_FOLDER,
    allowedChatIds: ALLOWED_CHAT_IDS.map(String),
    timezone: TIMEZONE,
    model: MODEL,
    transcribeModel: TRANSCRIBE_MODEL,
    maxSeconds: MAX_SECONDS,
    maxTags: MAX_TAGS,
    transcribeUrl: 'https://api.openai.com/v1/audio/transcriptions',
    tasksUrl: SUPABASE_URL.replace(/\/+$/, '') + '/rest/v1/tasks?on_conflict=source_url',
  },
}];

// Decides whether this update is something to act on at all.
//
// The allow list is checked here, before anything is downloaded, transcribed or paid for.
// A message from any other chat leaves without a reply: answering would confirm the bot
// exists to whoever found it.
const cfg = $('Config').first().json;
const update = $input.first().json || {};
const msg = update.message || update.channel_post || update;
const chat = msg.chat || {};
const media = msg.voice || msg.audio || null;

const chatId = chat.id === undefined || chat.id === null ? '' : String(chat.id);
const allowed = cfg.allowedChatIds.includes(chatId);
const hasAudio = !!(media && media.file_id);
const duration = Number(media && media.duration) || 0;
const tooLong = duration > cfg.maxSeconds;

return [{
  json: {
    chatId,
    messageId: msg.message_id === undefined ? null : msg.message_id,
    allowed,
    hasAudio,
    duration,
    tooLong,
    // Only an allowed chat is ever answered, and only about audio it actually sent.
    shouldTranscribe: allowed && hasAudio && !tooLong,
    shouldRefuse: allowed && hasAudio && tooLong,
    fileId: hasAudio ? media.file_id : null,
    mimeType: (media && media.mime_type) || 'audio/ogg',
    refusal: 'That recording is ' + duration + ' seconds, over the ' + cfg.maxSeconds
      + ' second limit. Send it in shorter pieces and I will file each one.',
  },
}];

// The transcript goes to workflow 03 to be turned into a note.
const cfg = $('Config').first().json;
const res = $input.first().json || {};
const text = String(res.text || '').trim();
if (!text) throw new Error('the transcription came back empty');

const schema = {
  type: 'object',
  required: ['title', 'cleaned_text', 'tags', 'type', 'related_project'],
  properties: {
    title: { type: 'string' },
    cleaned_text: { type: 'string' },
    tags: { type: 'array', items: { type: 'string' } },
    type: { type: 'string', enum: ['idea', 'task', 'note', 'log'] },
    related_project: { type: 'string' },
  },
};

return [{
  json: {
    model: cfg.model,
    max_retries: 1,
    schema,
    // Tidy, not retell. A summary would lose the thought the recording was made to keep.
    system: 'You file a spoken note for its author. Clean the transcript: drop fillers, '
      + 'false starts and repetitions, fix obvious speech-to-text errors, and keep '
      + 'everything else - the wording, the order, the details. Do not summarise, shorten '
      + 'or rephrase the substance. Write cleaned_text in the language that was spoken. '
      + 'title is a short noun phrase, at most 70 characters, no quotes or colons. tags are '
      + 'lowercase single words or hyphenated, at most ' + cfg.maxTags + '. type is task '
      + 'only when the author is telling themselves to do something. related_project is a '
      + 'name the author said, or "" when none was mentioned.',
    user: JSON.stringify({ transcript: text }),
  },
}];

// Builds the markdown file, its path, and the reply.
const cfg = $('Config').first().json;
const inspected = $('Inspect the message').first().json;
const transcript = String($('Transcribe').first().json.text || '').trim();
const answer = $input.first().json || {};
if (!answer.ok || !answer.data) {
  throw new Error('the note could not be structured: ' + JSON.stringify(answer.errors || []).slice(0, 200));
}
const d = answer.data;

const oneLine = (s, n) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, n);
const title = oneLine(d.title, 70) || 'Voice note';
const project = oneLine(d.related_project, 60);
const type = ['idea', 'task', 'note', 'log'].includes(d.type) ? d.type : 'note';

const tags = [...new Set((Array.isArray(d.tags) ? d.tags : [])
  .map((t) => String(t).toLowerCase().replace(/[^a-z0-9\u0400-\u04ff-]+/gi, '-').replace(/^-+|-+$/g, ''))
  .filter(Boolean))].slice(0, cfg.maxTags);

const slug = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 50) || 'note';
const now = DateTime.now().setZone(cfg.timezone);
// The message id is in the filename on purpose. Two notes dictated in the same minute
// would otherwise land on the same path and the second would overwrite the first.
const fileName = now.toFormat('yyyy-LL-dd-HHmm') + '-' + slug + '-' + inspected.messageId + '.md';
const path = cfg.vaultPath + '/' + cfg.inboxFolder + '/' + fileName;

// Quoted and escaped: a title with a colon or a quote in it would otherwise produce
// frontmatter that Obsidian cannot parse.
const yaml = (s) => '"' + String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';

const frontmatter = [
  '---',
  'created: ' + now.toISO(),
  'source: voice',
  'type: ' + type,
  'title: ' + yaml(title),
  'tags: [' + tags.join(', ') + ']',
  'project: ' + (project ? yaml(project) : '""'),
  'duration_seconds: ' + inspected.duration,
  '---',
].join('\n');

// The raw transcript is kept, folded, under the cleaned text. The cleaning is a judgement
// call by a model, and the only way to check it later is to still have the original.
const raw = transcript.split('\n').map((l) => '> ' + l).join('\n');
const markdown = [
  frontmatter,
  '',
  '# ' + title,
  '',
  String(d.cleaned_text || '').trim(),
  '',
  '> [!quote]- Raw transcript',
  raw,
  '',
].join('\n');

return [{
  json: {
    markdown,
    path,
    fileName,
    title,
    type,
    tags,
    project: project || null,
    isTask: type === 'task',
    chatId: inspected.chatId,
    task: type === 'task' ? {
      source: 'voice',
      // The note itself is the task's identity, so re-filing the same note cannot create
      // a second row.
      source_url: path,
      action: oneLine(title, 200),
      urgency: 'normal',
      deadline_hint: null,
      category: project ? oneLine(project, 40) : 'voice',
      context: oneLine(d.cleaned_text, 200) || null,
      status: 'open',
    } : null,
    reply: 'Filed: ' + title + '\n' + path + (type === 'task' ? '\nAlso added to tasks.' : ''),
  },
}];
